        if gaps:
            for j in gaps:
                c=row[j-1]
                out[i][j]=c
                for r in range(i+1):
                    out[r][j]=c
    for j in range(W):
        i=H-2
        while i>=0:
            if out[i][j]!=0: break
            i-=1
        if i<0: continue
        c=out[i][j]; t=i
        while t+1<H and out[t+1][j]==c: t+=1
        s=i-1
        while s-1>=0 and out[s-1][j]==0: s-=1
        if s>=0 and out[s][j]!=c:
            s2=i-1
            while s2-1>=0 and out[s2-1][j]==0:
                out[s2][j]=c; s2-=1
        i+=1
    return out

